function TagButton({ tags, limit = 50 }) {
  return tags.slice(0, limit).map((name) => (
    <button className="tag-pill tag-default" key={name} type="button">
      {name}
    </button>
  ));
}

export default TagButton;

import { useEffect, useState } from "react";
import getTags from "../services/getTags";

function usePopularTags() {
  const [tags, setTags] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const controller = new AbortController();

    async function loadTags() {
      try {
        const nextTags = await getTags(controller.signal);
        setTags(nextTags);
      } catch (requestError) {
        const isCanceled =
          requestError?.name === "CanceledError" ||
          requestError?.code === "ERR_CANCELED";

        if (!isCanceled) {
          setError("Tags list not available");
          console.error(requestError);
        }
      } finally {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      }
    }

    loadTags();

    return () => {
      controller.abort();
    };
  }, []);

  return { tags, loading, error };
}

export default usePopularTags;

